1	export type Cell = [number, number];
2	
3	const MIN_NEIGHBORS_TO_SURVIVE = 2;
4	const MAX_NEIGHBORS_TO_SURVIVE = 3;
5	const NEIGHBORS_TO_BE_BORN = 3;
6	
7	const OFFSETS = [-1, 0, 1];
8	
9	const key = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const neighborsOf = ([x, y]: Cell): Cell[] =>
12	  OFFSETS.flatMap((dx) =>
13	    OFFSETS.filter((dy) => dx !== 0 || dy !== 0).map(
14	      (dy): Cell => [x + dx, y + dy],
15	    ),
16	  );
17	
18	const countLiveNeighbors = (cell: Cell, liveCells: Set<string>): number =>
19	  neighborsOf(cell).filter((neighbor) => liveCells.has(key(neighbor))).length;
20	
21	const survives = (neighbors: number): boolean =>
22	  neighbors >= MIN_NEIGHBORS_TO_SURVIVE &&
23	  neighbors <= MAX_NEIGHBORS_TO_SURVIVE;
24	
25	const isBorn = (neighbors: number): boolean =>
26	  neighbors === NEIGHBORS_TO_BE_BORN;
27	
28	const dedupe = (cells: Cell[]): Cell[] => [
29	  ...new Map(cells.map((cell) => [key(cell), cell])).values(),
30	];
31	
32	const candidateCells = (liveCells: Cell[]): Cell[] =>
33	  dedupe(liveCells.flatMap((cell) => [cell, ...neighborsOf(cell)]));
34	
35	export function nextGeneration(liveCells: Cell[]): Cell[] {
36	  const alive = new Set(liveCells.map(key));
37	
38	  return candidateCells(liveCells).filter((cell) => {
39	    const neighbors = countLiveNeighbors(cell, alive);
40	
41	    return alive.has(key(cell)) ? survives(neighbors) : isBorn(neighbors);
42	  });
43	}
