1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	// The spec does not define an output ordering, so full-result comparisons sort
5	// both sides first. Sorting is value-based, so a missing or extra cell still fails.
6	const sorted = (cells: Cell[]): Cell[] =>
7	  [...cells].sort(([x, y], [otherX, otherY]) => y - otherY || x - otherX);
8	
9	describe("Game of Life - Next Generation", () => {
10	  it("should return an empty grid for an empty grid — [] -> []", () => {
11	    expect(nextGeneration([])).toEqual([]);
12	  });
13	
14	  it("should kill a single live cell with 0 neighbors (underpopulation) — [(0,0)] -> []", () => {
15	    expect(nextGeneration([[0, 0]])).toEqual([]);
16	  });
17	
18	  it("should kill both live cells when each has only 1 neighbor (underpopulation) — [(0,1), (1,1)] -> []", () => {
19	    expect(
20	      nextGeneration([
21	        [0, 1],
22	        [1, 1],
23	      ]),
24	    ).toEqual([]);
25	  });
26	
27	  // NOTE: the spec's Rule 2 illustration (`###`/`...`/`.#.` -> `.#.`/`.#.`/`...`)
28	  // is not reproducible under Conway's rules: its centre (1,1) is dead with 4
29	  // live neighbours, and the true next generation is [(1,-1),(0,1),(1,0),(2,1)].
30	  // The spec's *statement* of Rule 2 is sound, so we test that statement using
31	  // the block, where every live cell has exactly 3 neighbours and survives.
32	  it("should keep a live cell with 3 live neighbors alive (survival) — (0,0) of the block has 3 neighbors and survives", () => {
33	    const block: Cell[] = [
34	      [0, 0],
35	      [1, 0],
36	      [0, 1],
37	      [1, 1],
38	    ];
39	
40	    expect(nextGeneration(block)).toContainEqual([0, 0]);
41	  });
42	
43	  // NOTE: as with Rule 2, the spec's Rule 3 illustration is inaccurate. In
44	  // `###`/`.#.`/`###` the centre (1,1) has 6 live neighbours, not the 4 the
45	  // prose claims, and the drawn Gen 1 (`#.#`/`#.#`/`#.#`) is not the true next
46	  // generation. The asserted *behaviour* is nonetheless correct: the centre is
47	  // overpopulated and dies, so we assert its absence rather than the drawing.
48	  it("should kill a live cell with 4 live neighbors (overpopulation) — center (1,1) of `###`/`.#.`/`###` dies", () => {
49	    const grid: Cell[] = [
50	      [0, 0],
51	      [1, 0],
52	      [2, 0],
53	      [1, 1],
54	      [0, 2],
55	      [1, 2],
56	      [2, 2],
57	    ];
58	
59	    expect(nextGeneration(grid)).not.toContainEqual([1, 1]);
60	  });
61	
62	  it("should bring a dead cell with exactly 3 live neighbors to life (reproduction) — (1,1) of `##.`/`#..`/`...` becomes alive", () => {
63	    const grid: Cell[] = [
64	      [0, 0],
65	      [1, 0],
66	      [0, 1],
67	    ];
68	
69	    expect(nextGeneration(grid)).toContainEqual([1, 1]);
70	  });
71	
72	  it("should keep a block unchanged (still life) — [(0,0), (1,0), (0,1), (1,1)] -> unchanged", () => {
73	    const block: Cell[] = [
74	      [0, 0],
75	      [1, 0],
76	      [0, 1],
77	      [1, 1],
78	    ];
79	
80	    expect(sorted(nextGeneration(block))).toEqual(sorted(block));
81	  });
82	
83	  it.todo(
84	    "should turn a vertical blinker horizontal — [(0,0), (0,1), (0,2)] -> [(-1,1), (0,1), (1,1)]",
85	  );
86	
87	  it.todo(
88	    "should turn the horizontal blinker back to vertical — [(-1,1), (0,1), (1,1)] -> [(0,0), (0,1), (0,2)]",
89	  );
90	
91	  it.todo(
92	    "should handle negative coordinates — a blinker at negative coordinates oscillates",
93	  );
94	});
